<div class="toolbar crud-toolbar"><div><p class="eyebrow">Biblioteka strony</p><p class="lead"><code><?= $escape($identity->value()) ?></code></p></div><a class="button secondary" href="/admin/pages/builder?path=<?= rawurlencode($identity->value()) ?>">Wróć do bloków</a></div>
<form class="media-upload" method="post" enctype="multipart/form-data" action="/admin/media/upload"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="identity" value="<?= $escape($identity->value()) ?>"><label><span>Dodaj plik</span><input type="file" name="media" required></label><div><button type="submit">Prześlij</button><small>Maksymalny rozmiar i typy określa <code>setup.yml</code>.</small></div></form>
<div class="media-grid">
