        <?php if ($item->isImage()): ?><img src="<?= $escape($entry['preview']) ?>" alt="" loading="lazy"><?php else: ?><div class="media-file-icon"><?= $escape(strtoupper(pathinfo($item->name()->value(), PATHINFO_EXTENSION))) ?></div><?php endif; ?>
        <div class="media-card-body"><strong title="<?= $escape($item->name()->value()) ?>"><?= $escape($item->name()->value()) ?></strong><small><?= $escape($item->mimeType()) ?> · <?= $escape($entry['size']) ?><?= $item->width() === null ? '' : ' · ' . $item->width() . '×' . $item->height() . ' px' ?></small><div class="media-card-actions"><?php if ($item->isImage()): ?><button class="button compact secondary" type="button" data-media-preview="<?= $escape($entry['url']) ?>" data-media-preview-name="<?= $escape($item->name()->value()) ?>">Podgląd</button><?php else: ?><a class="button compact secondary" href="<?= $escape($entry['url']) ?>" target="_blank" rel="noopener">Otwórz</a><?php endif; ?><form method="post" action="/admin/media/delete" data-confirm="Usunąć ten plik? Operacji nie można cofnąć."><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="identity" value="<?= $escape($identity->value()) ?>"><input type="hidden" name="name" value="<?= $escape($item->name()->value()) ?>"><button type="submit" class="button compact danger-text">Usuń</button></form></div></div>
    </article>
<?php endforeach; ?>
</div>
